import assert from 'node:assert/strict';
import {readFileSync,readdirSync,existsSync,statSync} from 'node:fs';
import {spawnSync} from 'node:child_process';
import {inventory,repository,isDoc,sourceFingerprint,sha256} from '/workspaces/lorcana-online-tcg/scripts/documentation-lib.mjs';
process.chdir(repository);
const git=(...args)=>{const p=spawnSync('git',args,{encoding:null,maxBuffer:16*1024*1024});assert.equal(p.status,0,'Git inspection failed');return p.stdout;};
const names=(...args)=>git(...args).toString().trim().split('\n').filter(Boolean);
assert.equal(git('branch','--show-current').toString().trim(),'codex/play-04-opening-fixes');
assert.equal(git('rev-parse','main').toString().trim(),'775994a82f5f003c4c4831a20791d5e904ff3d6b');
const baseline=JSON.parse(readFileSync('.local/play04-opening-preservation.json','utf8'));
for(const [path,saved] of Object.entries(baseline)){assert.equal(sha256(readFileSync(path)),saved.sha256,'Private bytes changed');assert.equal(statSync(path).mode&0o777,saved.mode,'Private mode changed');assert.equal(spawnSync('git',['check-ignore','-q',path]).status,0);}
const expected=['apps/match-service/src/clock-service.ts','apps/match-service/tests/client-fixtures.mjs','apps/match-service/tests/clock-live.test.mjs','apps/match-service/tests/clock-service.test.mjs','apps/match-service/tests/clock-storage.test.mjs','apps/web/tests/clock-client.spec.ts','packages/db/src/clock-store.ts','packages/db/src/index.ts','packages/db/src/match-store.ts'].sort();
const source=inventory().filter(p=>!isDoc(p)||p.startsWith('docs/schemas/'));
assert.deepEqual(names('diff','--name-only','33e9a7a').filter(p=>!isDoc(p)||p.startsWith('docs/schemas/')).sort(),expected);
for(const path of inventory())assert.deepEqual(git('show',':'+path),readFileSync(path),'Staged canonical bytes differ: '+path);
const c=JSON.parse(readFileSync('docs/changes/CHG-20261016-003.json','utf8'));
assert.equal(c.status,'finalized');
const cumulative=new Set([...names('diff','--name-only','775994a'),...names('ls-files','--others','--exclude-standard')]);
for(const path of cumulative)assert(c.files.includes(path),'Missing cumulative coverage: '+path);
assert.equal(c.files.length,new Set(c.files).size);
const env=readFileSync('.env.local','utf8'),managed=JSON.parse(readFileSync('.local/database.json','utf8')),secrets=[];
for(const line of env.split('\n')){const i=line.indexOf('=');if(i>0&&/password|secret|token/i.test(line.slice(0,i))){const value=line.slice(i+1).trim().replace(/^['"]|['"]$/g,'');if(value.length>=12)secrets.push(value);}}
function collect(o){if(!o||typeof o!=='object')return;for(const [k,v] of Object.entries(o)){if(typeof v==='string'&&/password|secret|token/i.test(k)&&v.length>=12)secrets.push(v);else if(typeof v==='object')collect(v);}}
collect(managed);assert(secrets.length>0,'No private scan inputs');
let files=0,logs=0;
for(const path of inventory()){
 const bytes=readFileSync(path);for(const secret of secrets)assert(!bytes.includes(Buffer.from(secret)),'Private value found in owned file: '+path);files++;
 if(/^docs\/validation\/runs\/RUN-20261016-/.test(path)){
  const r=JSON.parse(bytes);if(r.log_path){assert.equal(sha256(readFileSync(r.log_path)),r.log_sha256,'Log digest mismatch');logs++;}
 }
}
for(const path of ['apps/web/tests/clock-client.spec.ts'])assert(!/from\s+['"][^'"]*match-service\/dist\//.test(readFileSync(path,'utf8')));
const processRoots=['/workspaces/lorcana-online-tcg/apps/match-service/dist/main.js','/workspaces/lorcana-online-tcg/apps/api/dist/main.js','/workspaces/lorcana-online-tcg/apps/worker/dist/main.js'];
for(const id of readdirSync('/proc').filter(x=>/^\d+$/.test(x))){
 let args;try{args=readFileSync('/proc/'+id+'/cmdline','utf8').split('\0');}catch{continue;}
 if(args[0]?.includes('node'))assert(!args.slice(1).some(a=>processRoots.includes(a)||/\/(?:clock-child|gateway-child|client-host)\.mjs$/.test(a)),'Owned runtime child remains: '+id);
}
for(const f of ['/proc/net/tcp','/proc/net/tcp6'])if(existsSync(f))for(const line of readFileSync(f,'utf8').split('\n').slice(1)){const cols=line.trim().split(/\s+/);if(cols[3]==='0A'){const port=parseInt(cols[1].split(':').at(-1),16);assert(![5173,3001,3002].includes(port),'Foundation listener remains');}}
console.log('PASS private bytes/modes/ignores, main unchanged, exactly9 executable fix files, native rules/engine/SQL/public schemas/client runtime/dependencies unchanged, canonical staged source and cumulative branch coverage.');
console.log(JSON.stringify({source_fingerprint:sourceFingerprint(),canonical_source_files:source.length,scanned_owned_files:files,checked_local_run_logs:logs,cumulative_files:c.files.length,peak_memory:'unknown',device_acceptance:'not_run',host_settings:'unchanged'}));
